from playwright.sync_api import sync_playwright
from pathlib import Path
import json
root=Path(__file__).parent
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox','--disable-dev-shm-usage','--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--enable-webgl','--ignore-gpu-blocklist']);page=b.new_page(viewport={'width':1100,'height':750});errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
 page.set_content((root/'index.html').read_text(),timeout=25000);page.wait_for_function('window.__thousand?.state.teeAtlasLoaded',timeout=30000);mode=page.evaluate('window.__thousand.state.renderer');page.locator('#paths').click();steps=[]
 for dest,name in [('lantern','The Last Lantern'),('balcony','Balcony of Arrivals'),('homeBridge','Upper residential bridge'),('ribbonWalk','Ribbon Walk')]:
  before=page.evaluate('window.__thousand.state.yaw');page.locator('#localChoices button').filter(has_text=name).first.click();page.wait_for_function(f"window.__thousand.state.current==='{dest}' && !window.__thousand.state.travel",timeout=35000);state=page.evaluate('window.__thousand.state');assert state['yaw']==before;steps.append(dest)
 page.mouse.move(500,350);page.mouse.down();page.mouse.move(500,90);page.mouse.up();assert page.locator('#localChoices .localRow').count()==2
 page.screenshot(path=str(root/'browser-ribbon-paths.png'));page.locator('#localChoices button[aria-label="Look toward Houses Above the Market"]').click();state=page.evaluate('window.__thousand.state');assert state['current']=='ribbonWalk' and not state['travel'];page.locator('#paths').click();page.wait_for_timeout(750);page.screenshot(path=str(root/'browser-ribbon-look.png'));page.locator('#paths').click();page.locator('#localChoices button').filter(has_text='Houses Above the Market').first.click();page.wait_for_timeout(700);page.locator('#walkBack').click();page.wait_for_function("window.__thousand.state.current==='ribbonWalk'&&!window.__thousand.state.travel",timeout=20000);page.locator('#localChoices button').filter(has_text='Houses Above the Market').first.click();page.wait_for_function("window.__thousand.state.current==='homes'&&!window.__thousand.state.travel",timeout=35000);steps.append('homes');page.locator('#walkBack').click();page.wait_for_function("window.__thousand.state.current==='ribbonWalk'&&!window.__thousand.state.travel",timeout=35000);steps.append('ribbonWalk');assert not errors;assert not page.locator('#err').text_content();res={'status':'pass','renderer':mode,'actual_click_route':steps,'offscreen_routes':2,'explicit_look':True,'midwalk_reversal':True,'backtrack':True,'camera_preserved':True,'errors':errors,'scope':'Chromium set_content, actual user controls and live walking; not hosted or full graph playthrough'};(root/'evidence'/'navigation-browser.json').write_text(json.dumps(res,indent=2));print(res);b.close()
